"""Assemble manually reviewed Morocco findings from bounded evidence; no network."""
import json
from pathlib import Path
D=Path(__file__).parent
E=D/'evidence'
def meta(n): return json.loads((E/(n+'.json')).read_text())
def source(url,claim,path=None):return dict(url=url,claim=claim,evidence_path=path)
def size(value,unit,date,url,path,quality,note):return dict(value=value,unit=unit,date=date,source_url=url,evidence_path=path,quality=quality,note=note)
def query(n,text,count,match,note):
 m=meta(n)
 p=m['payload']
 if p and 'csrf_token' in p:p=dict(p,csrf_token='<fresh anonymous form token; not persisted>')
 return dict(text=text,method=m['method'],url=m['url'],payload=p,checked_at_utc=m['checked_at_utc'],http_status=m['status'],effective_url=m['effective_url'],result_count=count,count_note=note,match_type=match,evidence_path=m['evidence_path'],metadata_path=m['metadata_path'])
def robots(n,decision,note):
 m=meta(n+'-robots');return dict(url=m['url'],status=m['status'],checked_at_utc=m['checked_at_utc'],evidence_path=m['metadata_path'],decision=decision,note=note)
def book(title,author,id,url,isbn,holdings,path):return dict(title=title,author=author,record_id=id,record_url=url,isbn=isbn,holdings=holdings,evidence_path=path)
def lib(id,name,recommendation,scope,sz,family,proof,q,books,rob,access,needs,blockers,adapter):return dict(id=id,name=name,recommendation=recommendation,scope=scope,size=sz,platform=dict(family=family,name=family,proof=proof,evidence_path=q['evidence_path']),query=q,books=books,robots=rob,reader_access=access,integration=dict(existing_adapter=adapter,needs=needs,blockers=blockers,live_app_tested=False))
